      function handleSubmit(event) {
        event.preventDefault();

        const fieldsets = Array.from(event.currentTarget.querySelectorAll("fieldset[data-question-id]"));
        let firstInvalid = null;
        let score = 0;

        fieldsets.forEach((fieldset) => {
          const selected = Array.from(fieldset.querySelectorAll('input[type="checkbox"]:checked')).map((input) => input.value);
          const answers = JSON.parse(fieldset.getAttribute("data-answer-key") || "[]");
          const questionId = fieldset.getAttribute("data-question-id");
          const error = fieldset.querySelector(".field-error");
          const questionChecks = Array.from(fieldset.querySelectorAll('input[type="checkbox"]'));
          const isValid = selected.length > 0;
          const isCorrect =
            selected.length === answers.length &&
            selected.every((value) => answers.includes(value)) &&
            answers.every((value) => selected.includes(value));

          fieldset.setAttribute("aria-invalid", String(!isValid));
          error.hidden = isValid;
          questionChecks.forEach((input) => {
            input.setAttribute("aria-invalid", String(!isValid));
