        margin-bottom: 0.35rem;
      }

      .required-mark {
        color: var(--error);
      }

      .field-help,
      .field-error {
        margin: 0.25rem 0 0;
        font-size: 0.95rem;
      }

      .field-help {
        color: var(--muted);
      }

      .field-error {
        color: var(--error);
        font-weight: 600;
      }

      .option-list {
        list-style: none;
        margin: 1rem 0 0;
        padding: 0;
        display: grid;
        gap: 0.75rem;
      }

      .option-item {
        display: flex;
        align-items: flex-start;
        gap: 0.75rem;
        padding: 0.8rem 0.9rem;
