        background: var(--surface-alt);
      }

      .option-item:hover {
        border-color: #c7d7f6;
      }

      .option-item input {
        margin-top: 0.2rem;
        width: 1.05rem;
        height: 1.05rem;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .option-item label {
        display: block;
        cursor: pointer;
        font-weight: 500;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
        justify-content: space-between;
        padding-top: 0.25rem;
      }

      .submit-button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        padding: 0.95rem 1.35rem;
        min-height: 3rem;
        cursor: pointer;
        box-shadow: 0 10px 24px rgba(54, 99, 233, 0.28);
      }

      .submit-button:hover {
        filter: brightness(1.03);
      }

      .submit-button:active {
        transform: translateY(1px);
      }

      .result {
        margin: 0;
        color: var(--muted);
        font-weight: 600;
      }

      .result[data-state="success"] {
        color: var(--success);
      }

      .result[data-state="error"] {
        color: var(--error);
      }

      @media (max-width: 40rem) {
        .page-shell {
          padding-top: 4.25rem;
        }

        .actions {
          align-items: stretch;
        }

        .submit-button {
          width: 100%;
        }
