      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-alt: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --accent: ButtonText;
          --accent-strong: ButtonText;
          --success: CanvasText;
          --error: CanvasText;
          --shadow: none;
        }

        .skip-link,
        .quiz-card,
        .form-field,
