   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="root"></div>

     <script>
       const quizData = [
         {
           id: "q1",
           prompt: "Which of these are programming languages?",
           helpText: "Select all that apply.",
           options: [
             { id: "q1-python", label: "Python", correct: true },
             { id: "q1-javascript", label: "JavaScript", correct: true },
             { id: "q1-css", label: "CSS", correct: false },
             { id: "q1-sql", label: "SQL", correct: true },
           ],
         },
         {
           id: "q2",
           prompt: "Which of these are compiled languages?",
           options: [
             { id: "q2-c", label: "C", correct: true },
             { id: "q2-rust", label: "Rust", correct: true },
             { id: "q2-python", label: "Python", correct: false },
             { id: "q2-go", label: "Go", correct: true },
           ],
         },
         {
           id: "q3",
           prompt: "Which of these are markup or query languages?",
           options: [
             { id: "q3-html", label: "HTML", correct: true },
             { id: "q3-xml", label: "XML", correct: true },
             { id: "q3-sql", label: "SQL", correct: true },
             { id: "q3-csharp", label: "C#", correct: false },
           ],
         },
       ];

       const state = {
         statusId: "quiz-status",
       };

       function App() {
         const main = document.createElement("main");
         main.id = "main-content";
         main.className = "page-shell";

         const hero = document.createElement("header");
         hero.className = "hero";
         hero.innerHTML = `
           <p class="eyebrow">Quick knowledge check</p>
           <h1>Computer languages quiz</h1>
           <p class="lede">Pick every answer that fits each question. Some questions have more than one correct choice.</p>
         `;

         const card = document.createElement("section");
         card.className = "quiz-card";
         card.setAttribute("aria-labelledby", "quiz-title");

         const form = document.createElement("form");
         form.className = "quiz-form";
         form.noValidate = true;
         form.innerHTML = `
           <h2 id="quiz-title" class="sr-only">Quiz questions</h2>
         `;

         quizData.forEach((question, index) => {
           form.appendChild(QuestionCard(question, index));
         });

         const actions = document.createElement("div");
         actions.className = "actions";
         actions.innerHTML = `
           <button class="submit-button" type="submit">Submit answers</button>
           <p class="result" id="${state.statusId}" aria-live="polite">Answer all three questions and submit to see your score.</p>
         `;

         form.appendChild(actions);
         form.addEventListener("submit", handleSubmit);

         card.appendChild(form);
         main.append(hero, card);
         return main;
       }

       function QuestionCard(question, index) {
         const container = document.createElement("div");
         container.className = "form-field";

         const helpId = `${question.id}-help`;
         const errorId = `${question.id}-error`;

         const legendText = document.createElement("legend");
         legendText.innerHTML = `
           ${question.prompt}
           <span class="required-mark" aria-hidden="true"> *</span>
           <span class="sr-only"> required</span>
         `;

         const fieldset = document.createElement("fieldset");
         fieldset.setAttribute("aria-required", "true");
         fieldset.setAttribute("data-question-id", question.id);
         fieldset.setAttribute("data-answer-key", JSON.stringify(question.options.filter((option) => option.correct).map((option) => option.id)));
         fieldset.setAttribute("aria-describedby", `${helpId} ${errorId}`);
         fieldset.appendChild(legendText);

         if (index === 0) {
           const help = document.createElement("p");
           help.className = "field-help";
           help.id = helpId;
           help.textContent = question.helpText;
           fieldset.appendChild(help);
         } else {
           const help = document.createElement("p");
           help.className = "field-help";
           help.id = helpId;
           help.textContent = "Select all answers you think are correct.";
           fieldset.appendChild(help);
         }

         const error = document.createElement("p");
         error.className = "field-error";
         error.id = errorId;
         error.hidden = true;
         error.textContent = "Select at least one answer before submitting.";
         fieldset.appendChild(error);

         const options = document.createElement("ul");
         options.className = "option-list";

         question.options.forEach((option) => {
           const item = document.createElement("li");
           item.className = "option-item";

           const inputId = option.id;
           const label = document.createElement("label");
           label.setAttribute("for", inputId);
           label.textContent = option.label;

           const input = document.createElement("input");
           input.type = "checkbox";
           input.name = question.id;
           input.id = inputId;
           input.value = option.id;

           item.append(input, label);
           options.appendChild(item);
         });

         fieldset.appendChild(options);
         container.appendChild(fieldset);
         return container;
       }

       function handleSubmit(event) {
         event.preventDefault();

         const fieldsets = Array.from(event.currentTarget.querySelectorAll("fieldset[data-question-id]"));
         let firstInvalid = null;
         let score = 0;

         fieldsets.forEach((fieldset) => {
           const selected = Array.from(fieldset.querySelectorAll('input[type="checkbox"]:checked')).map((input) => input.value);
           const answers = JSON.parse(fieldset.getAttribute("data-answer-key") || "[]");
           const error = fieldset.querySelector(".field-error");
           const questionChecks = Array.from(fieldset.querySelectorAll('input[type="checkbox"]'));
           const isValid = selected.length > 0;
           const isCorrect =
             selected.length === answers.length &&
             selected.every((value) => answers.includes(value)) &&
             answers.every((value) => selected.includes(value));

           if (isValid) {
             fieldset.removeAttribute("aria-invalid");
           } else {
             fieldset.setAttribute("aria-invalid", "true");
           }
           error.hidden = isValid;
           questionChecks.forEach((input) => {
             if (isValid) {
               input.removeAttribute("aria-invalid");
             } else {
               input.setAttribute("aria-invalid", "true");
             }
           });

           if (!isValid && !firstInvalid) {
             firstInvalid = fieldset.querySelector('input[type="checkbox"]');
           }

           if (isCorrect) {
             score += 1;
           }
         });

         const result = document.getElementById(state.statusId);
         if (firstInvalid) {
           result.textContent = "Please answer every question before submitting.";
           result.dataset.state = "error";
           firstInvalid.focus();
           return;
         }

         result.dataset.state = "success";
         result.textContent = `You scored ${score} out of ${fieldsets.length}.`;
       }

       document.getElementById("root").appendChild(App());
     </script>
